	for _, msg := range session.Messages {
		switch msg.Info.Role {
		case "user":
			text := opencode.ExtractTextFromParts(msg.Parts)
			if text != "" {
				entries = append(entries, Entry{
					Type:    EntryTypeUser,
					Content: text,
				})
			}
		case "assistant":
